import json
import sys
import argparse
import ast

def parse_arguments():
    parser = argparse.ArgumentParser()
    parser.add_argument('--flags', type=str, required=True)
    parser.add_argument('--token', type=str, required=True)
    return parser.parse_args()

def load_token(token_path):
    with open(token_path, 'r') as f:
        token_data = json.load(f)
    return token_data

def load_flags(flags_path):
    with open(flags_path, 'r') as f:
        flags_data = json.load(f)
    return flags_data

def evaluate_flag(flag, token_attrs):
    try:
        expr = flag['expr']
        # Safely evaluate the expression with token attributes
        safe_expr = ast.literal_eval(expr)
        # Replace placeholders with actual values
        for key, value in token_attrs.items():
            safe_expr = safe_expr.replace(f'{{{key}}}', str(value))
        return eval(safe_expr)
    except:
        return False

def check_roles(roles_list, flag_roles):
    return any(role in flag_roles for role in roles_list)

def main():
    args = parse_arguments()
    token_data = load_token(args.token)
    flags_data = load_flags(args.flags)

    for flag_name, flag_info in flags_data.items():
        if check_roles(token_data['roles'], flag_info['roles']):
            result = evaluate_flag(flag_info, token_data['attributes'])
            print(f"{flag_name}: {result}")

if __name__ == "__main__":
    main()

import sys
import json
import hmac
import hashlib
import argparse

def evaluate_expression(expr, attributes):
    try:
        env = {'role': attributes.get('role', ''), **attributes}
        return eval(expr, {'__builtins__': None}, env)
    except:
        return False

def main():
    if len(sys.argv) != 4:
        print("Usage: python featureflags.py <flags_path> <token_path> <key_path>")
        sys.exit(1)

    flags_path = sys.argv[1]
    token_path = sys.argv[2]
    key_path = sys.argv[3]

    with open(flags_path, 'r') as f:
        flags = json.load(f)

    with open(token_path, 'r') as f:
        payload_line = f.readline().strip()
        signature_line = f.readline().strip()

    with open(key_path, 'r') as f:
        key = f.read().strip()

    payload = json.loads(payload_line)
    role = payload.get('role', '')
    attributes = payload.get('attributes', {})

    if not role:
        sys.exit(0)

    expected_signature = hmac.new(
        key.encode('utf-8'),
        payload_line.encode('utf-8'),
        hashlib.sha256
    ).hexdigest()

    if expected_signature != signature_line:
        sys.exit(0)

    for flag_name, flag in flags.items():
        if flag['role'] == role:
            result = evaluate_expression(flag['expr'], attributes)
            print(f"{flag_name}: {result}")

if __name__ == "__main__":
    main()
